package sigma_algebra

import (
	. "github.com/euc-ai/xugo/library/authoring"
	"github.com/euc-ai/xugo/library/proofs/nat_num/nat_order"
	"github.com/euc-ai/xugo/library/proofs/nat_num/peano"
	"github.com/euc-ai/xugo/library/proofs/sets/set_algebra"
	"github.com/euc-ai/xugo/library/registry"
)

// PiLambda — a λ-system containing a π-system C also contains the σ-algebra
// generated by C. In the least λ-system containing C, fixing one factor
// of intersection first in C and then in the whole system gives closure
// under intersections. Finite unions and disjointification give countable
// union closure.
var PiLambda = piLambdaThm{family.Add(registry.ProofEntry{
	Name: "PiLambda",
	Key:  "prop_6529156044384597",
	Build: family.Sections(Statement{
		Binders:    "∀Ω:set(A). ∀C D:set(set(A)).",
		Hypotheses: []string{"pi_system_on(Ω, C)", "lambda_system_on(Ω, D)", "C ⊆ D"},
		Conclusion: "generated_sigma(Ω, C) ⊆ D",
		Abbrev: Abbrev{
			{Name: "earlier", Text: "λp:(num → set(A)). λn:num. ⋃image(p, {k:num | k < n})"},
			{Name: "part", Text: "λp:(num → set(A)). λn:num. p(n) ∖ «earlier»(p, n)"},
		},
	}, func(ctx *Script, headline string) *GoalStackNode {
		emptyAndDisjointUnions := ctx.Lemma(Statement{
			Binders:    "∀Ω:set(A). ∀D:set(set(A)).",
			Hypotheses: []string{"lambda_system_on(Ω, D)"},
			Conclusion: "∅ ∈ D ∧ (∀s t:set(A). s ∈ D ∧ t ∈ D ∧ s ∩ t = ∅ ⇒ s ∪ t ∈ D)",
		}, func(a *Argument, Ω *Expr[Set[A]], D *Expr[Set[Set[A]]], lambda Fact) {
			laws := a.Conjuncts(
				a.Unfolded(lambda, LambdaSystemDef),
				"the sets lie within the carrier",
				"the system contains the carrier",
				"relative complements stay in the system",
				"countable disjoint unions stay in the system")
			carrier, complement, countable := laws[1], laws[2], laws[3]
			empty := a.Have(
				"the complement of the carrier is empty",
				"∅ ∈ D",
				By(Normalized, carrier, complement.At(Ω), set_algebra.DiffEqEmpty.At(Ω)))
			unions := a.Have(
				"the union of a disjoint pair lies in the system",
				"∀s t:set(A). s ∈ D ∧ t ∈ D ∧ s ∩ t = ∅ ⇒ s ∪ t ∈ D",
				Derive(func(b *Argument) {
					b.FixAs[Set[A]]("s")
					b.FixAs[Set[A]]("t")
					pair := b.Assume()
					q, qDef := b.LetAs[Fun[Nat, Set[A]]]("q", "λn:num. COND(n = 0, s, COND(n = suc(0), t, ∅))")
					terms := b.Have(
						"the padded sequence takes only s, t and the empty set",
						"∀n:num. q(n) ∈ D",
						By(qDef, pair, empty))
					disjoint := b.Have(
						"distinct terms of the padded sequence are disjoint",
						"∀i j:num. i ≠ j ⇒ q(i) ∩ q(j) = ∅",
						BySets(qDef, pair))
					union := b.Have(
						"padding leaves the union unchanged",
						"⋃image(q, 𝕌) = s ∪ t",
						BySets(qDef, peano.SucNotZero.At(b.TermAs[Nat]("0"))))
					b.Show(
						"countable disjoint union closure gives the binary union",
						By(countable.At(q), terms, disjoint, union))
				}))
			a.Show(
				"the system has the empty set and disjoint binary unions",
				By(empty, unions))
		})
		relativeDifference := ctx.Lemma(Statement{
			Binders:    "∀Ω:set(A). ∀D:set(set(A)). ∀s t:set(A).",
			Hypotheses: []string{"lambda_system_on(Ω, D)", "s ∈ D", "t ∈ D", "s ⊆ t"},
			Conclusion: "t ∖ s ∈ D",
		}, func(
			a *Argument,
			Ω *Expr[Set[A]],
			D *Expr[Set[Set[A]]],
			s, t *Expr[Set[A]],
			lambda, inS, inT, included Fact,
		) {
			laws := a.Conjuncts(
				a.Unfolded(lambda, LambdaSystemDef),
				"the sets lie within the carrier",
				"the system contains the carrier",
				"relative complements stay in the system",
				"countable disjoint unions stay in the system")
			inside, complement := laws[0], laws[2]
			disjoint := a.Have(
				"s is disjoint from the complement of t",
				"s ∩ (Ω ∖ t) = ∅",
				BySets(included))
			union := a.Have(
				"their disjoint union is in the system",
				"s ∪ (Ω ∖ t) ∈ D",
				By(lambda, inS, inT, disjoint, complement.At(t), At(emptyAndDisjointUnions, Ω, D)))
			difference := a.Have(
				"the complement of that union is the relative difference",
				"Ω ∖ (s ∪ (Ω ∖ t)) = t ∖ s",
				BySets(inside, inT))
			a.Show(
				"the system contains the complement of the union",
				By(Normalized, complement.At(a.TermAs[Set[A]]("s ∪ (Ω ∖ t)")), union, difference))
		})
		fixedIntersection := ctx.Lemma(Statement{
			Binders:    "∀Ω:set(A). ∀D:set(set(A)). ∀s:set(A).",
			Hypotheses: []string{"lambda_system_on(Ω, D)", "s ∈ D"},
			Conclusion: "lambda_system_on(Ω, {t:set(A) | t ∈ D ∧ s ∩ t ∈ D})",
		}, func(a *Argument, Ω *Expr[Set[A]], D *Expr[Set[Set[A]]], s *Expr[Set[A]], lambda, inS Fact) {
			laws := a.Conjuncts(
				a.Unfolded(lambda, LambdaSystemDef),
				"the sets lie within the carrier",
				"the system contains the carrier",
				"relative complements stay in the system",
				"countable disjoint unions stay in the system")
			inside, carrier, complement, countable := laws[0], laws[1], laws[2], laws[3]
			H, hDef := a.LetAs[Set[Set[A]]]("H", "{t:set(A) | t ∈ D ∧ s ∩ t ∈ D}")
			within := a.Have(
				"every set in H lies in the carrier because H is a subfamily of D",
				"H ⊆ {t:set(A) | t ⊆ Ω}",
				BySets(hDef, inside))
			carrierInH := a.Have(
				"the carrier belongs to H",
				"Ω ∈ H",
				Derive(func(b *Argument) {
					identity := b.Have(
						"intersecting s with the carrier leaves s",
						"s ∩ Ω = s",
						BySets(inside, inS))
					intersection := b.Have(
						"the intersection belongs to D",
						"s ∩ Ω ∈ D",
						By(Normalized, identity, inS))
					b.Show(
						"the carrier and its intersection with s both belong to D",
						BySets(hDef, intersection, carrier))
				}))
			complements := a.Have(
				"H is closed under relative complements",
				"∀t:set(A). t ∈ H ⇒ Ω ∖ t ∈ H",
				Derive(func(b *Argument) {
					t := b.FixAs[Set[A]]("t")
					inH := b.Assume()
					both := b.Have(
						"t and its intersection with s lie in D",
						"t ∈ D ∧ s ∩ t ∈ D",
						BySets(hDef, inH))
					sub := b.Have(
						"the intersection is contained in s",
						"s ∩ t ⊆ s",
						BySets())
					difference := b.Have(
						"intersecting the complement of t with s removes the intersection from s",
						"s ∩ (Ω ∖ t) = s ∖ (s ∩ t)",
						BySets(inside, inS))
					bothComplements := b.Have(
						"the complement and its intersection with s lie in D",
						"Ω ∖ t ∈ D ∧ s ∩ (Ω ∖ t) ∈ D",
						SplitConj(
							Case(
								"the complement of t lies in D",
								By(both, complement.At(t))),
							Case(
								"removing the intersection from s leaves a set of D",
								By(
									Normalized,
									lambda,
									inS,
									both,
									sub,
									difference,
									At(relativeDifference, Ω, D, b.TermAs[Set[A]]("s ∩ t"), s)))))
					b.Show(
						"so the relative complement lies in H",
						BySets(hDef, bothComplements))
				}))
			unions := a.Have(
				"H is closed under countable disjoint unions",
				"∀p:(num → set(A)). (∀n:num. p(n) ∈ H) ∧ (∀i j:num. i ≠ j ⇒ p(i) ∩ p(j) = ∅) ⇒ ⋃image(p, 𝕌) ∈ H",
				Derive(func(b *Argument) {
					p := b.FixAs[Fun[Nat, Set[A]]]("p")
					given := b.Conjuncts(
						b.Assume(),
						"each term is in H",
						"the terms are pairwise disjoint")
					terms, disjoint := given[0], given[1]
					r, rDef := b.LetAs[Fun[Nat, Set[A]]]("r", "λn:num. s ∩ p(n)")
					inD := b.Have(
						"both the sequence and its intersections have terms in D",
						"(∀n:num. p(n) ∈ D) ∧ (∀n:num. r(n) ∈ D)",
						SplitConj(
							Case(
								"the original terms lie in D",
								BySets(hDef, terms)),
							Case(
								"the intersected terms lie in D",
								Derive(func(c *Argument) {
									n := c.FixAs[Nat]("n")
									trace := c.Have(
										"membership in H puts the intersection in D",
										"s ∩ p(n) ∈ D",
										BySets(hDef, terms.At(n)))
									c.Show(
										"r gives exactly those intersections",
										By(Normalized, rDef, trace))
								}))))
					disjointTraces := b.Have(
						"the intersected terms remain disjoint",
						"∀i j:num. i ≠ j ⇒ r(i) ∩ r(j) = ∅",
						BySets(rDef, disjoint))
					distribution := b.Have(
						"intersection with s distributes over the union",
						"⋃image(r, 𝕌) = s ∩ ⋃image(p, 𝕌)",
						BySets(rDef))
					both := b.Have(
						"both unions lie in D",
						"⋃image(p, 𝕌) ∈ D ∧ s ∩ ⋃image(p, 𝕌) ∈ D",
						SplitConj(
							Case(
								"the union of the terms lies in D",
								By(countable.At(p), inD, disjoint)),
							Case(
								"s meets the union in the union of the intersected terms, which lies in D",
								By(countable.At(r), inD, disjointTraces, distribution))))
					b.Show(
						"the original union is therefore in H",
						BySets(hDef, both))
				}))
			a.Show(
				"the sets whose intersection with s lies in D form a λ-system",
				By(within, carrierInH, complements, unions, LambdaSystemDef.At(Ω, H)))
		})
		sigmaFromIntersections := ctx.Lemma(Statement{
			Binders:    "∀Ω:set(A). ∀D:set(set(A)).",
			Hypotheses: []string{"lambda_system_on(Ω, D)", "∀s t:set(A). s ∈ D ∧ t ∈ D ⇒ s ∩ t ∈ D"},
			Conclusion: "sigma_algebra_on(Ω, D)",
		}, func(a *Argument, Ω *Expr[Set[A]], D *Expr[Set[Set[A]]], lambda, intersections Fact) {
			laws := a.Conjuncts(
				a.Unfolded(lambda, LambdaSystemDef),
				"the sets lie within the carrier",
				"the system contains the carrier",
				"relative complements stay in the system",
				"countable disjoint unions stay in the system")
			inside, carrier, complement, countable := laws[0], laws[1], laws[2], laws[3]
			unions := a.Have(
				"De Morgan gives binary union closure",
				"∀s t:set(A). s ∈ D ∧ t ∈ D ⇒ s ∪ t ∈ D",
				Derive(func(b *Argument) {
					s := b.FixAs[Set[A]]("s")
					t := b.FixAs[Set[A]]("t")
					both := b.Assume()
					sComp := b.TermAs[Set[A]]("Ω ∖ s")
					tComp := b.TermAs[Set[A]]("Ω ∖ t")
					compMeet := b.TermAs[Set[A]]("(Ω ∖ s) ∩ (Ω ∖ t)")
					deMorgan := b.Have(
						"the union is the complement of the intersection of the complements",
						"s ∪ t = Ω ∖ ((Ω ∖ s) ∩ (Ω ∖ t))",
						BySets(inside, both))
					b.Show(
						"intersections and complements keep the union in D",
						By(
							both,
							complement.At(s),
							complement.At(t),
							intersections.At(sComp, tComp),
							complement.At(compMeet),
							deMorgan))
				}))
			differences := a.Have(
				"intersecting with a complement gives difference closure",
				"∀s t:set(A). s ∈ D ∧ t ∈ D ⇒ s ∖ t ∈ D",
				Derive(func(b *Argument) {
					s := b.FixAs[Set[A]]("s")
					t := b.FixAs[Set[A]]("t")
					both := b.Assume()
					difference := b.Have(
						"difference restricts s to the relative complement of t",
						"s ∖ t = s ∩ (Ω ∖ t)",
						BySets(inside, both))
					b.Show(
						"the difference belongs to D",
						By(Normalized, both, complement.At(t), intersections.At(s, b.TermAs[Set[A]]("Ω ∖ t")), difference))
				}))
			countableUnions := a.Have(
				"disjointification gives countable union closure",
				"∀p:(num → set(A)). (∀n:num. p(n) ∈ D) ⇒ ⋃image(p, 𝕌) ∈ D",
				Derive(func(b *Argument) {
					b.FixAs[Fun[Nat, Set[A]]]("p")
					terms := b.Assume()
					prefixes := b.Have(
						"the earlier unions belong to D",
						"∀n:num. «earlier»(p, n) ∈ D",
						Derive(func(c *Argument) {
							c.Induct("n")
							c.Base(
								"the earlier union at zero is empty",
								func(d *Argument) {
									empty := d.Have(
										"no index lies below zero",
										"«earlier»(p, 0) = ∅",
										BySets(nat_order.LessThanZeroClause))
									d.Show(
										"the empty earlier union belongs to D",
										By(empty, lambda, At(emptyAndDisjointUnions, Ω, D)))
								})
							c.Step(
								"the earlier union at suc(n) adds one term",
								func(d *Argument, previous Fact) {
									n := d.TermAs[Nat]("n")
									grown := d.Have(
										"the indices before suc(n) include n and all those before n",
										"«earlier»(p, suc(n)) = «earlier»(p, n) ∪ p(n)",
										BySets(nat_order.LessThanSucClause))
									d.Show(
										"the larger earlier union is in D by binary union closure",
										By(
											terms.At(n),
											grown,
											previous,
											unions.At(d.TermAs[Set[A]]("«earlier»(p, n)"), d.TermAs[Set[A]]("p(n)"))))
								})
						}))
					parts := b.Have(
						"each term with the earlier union removed is in D",
						"∀n:num. «part»(p, n) ∈ D",
						By(terms, prefixes, differences))
					disjoint := b.Have(
						"the resulting pieces are pairwise disjoint",
						"∀i j:num. i ≠ j ⇒ «part»(p, i) ∩ «part»(p, j) = ∅",
						Derive(func(c *Argument) {
							c.FixAs[Nat]("i")
							c.FixAs[Nat]("j")
							distinct := c.Assume()
							order := c.Have(
								"distinct indices are strictly ordered",
								"i < j ∨ j < i",
								ByArith(distinct))
							c.Show(
								"the later piece leaves out the earlier piece",
								BySets(order))
						}))
					first := b.Have(
						"each point in the union belongs to a first term",
						"∀x:A. (∃n:num. x ∈ p(n)) ⇒ ∃m:num. x ∈ p(m) ∧ (∀k:num. k < m ⇒ x ∉ p(k))",
						By(nat_order.WellOrdering))
					sameUnion := b.Have(
						"each point belongs to the piece at its first index, so the union is unchanged",
						"⋃image(«part»(p), 𝕌) = ⋃image(p, 𝕌)",
						BySets(first))
					b.Show(
						"the disjoint pieces have their union in D",
						By(countable.At(b.TermAs[Fun[Nat, Set[A]]]("«part»(p)")), parts, disjoint, sameUnion))
				}))
			a.Show(
				"closure under countable unions makes D a σ-algebra",
				By(inside, carrier, complement, countableUnions, SigmaAlgebraOnDef.At(Ω, D)))
		})
		return ctx.Theorem(headline, func(
			a *Argument,
			Ω *Expr[Set[A]],
			C, D *Expr[Set[Set[A]]],
			pi, lambdaD, cInD Fact,
		) {
			laws := a.Conjuncts(
				a.Unfolded(lambdaD, LambdaSystemDef),
				"the sets of D lie within the carrier",
				"D contains the carrier",
				"D contains relative complements",
				"D contains countable disjoint unions")
			piLaws := a.Unfolded(pi, PiSystemDef)
			L, lDef := a.LetAs[Set[Set[A]]]("L", "⋂{H:set(set(A)) | lambda_system_on(Ω, H) ∧ C ⊆ H}")
			members := a.Have(
				"L consists of the sets in every λ-system containing C",
				"∀s:set(A). s ∈ L ⇔ ∀H:set(set(A)). lambda_system_on(Ω, H) ∧ C ⊆ H ⇒ s ∈ H",
				BySets(lDef))
			generators := a.Have(
				"each generator belongs to every such system",
				"C ⊆ L",
				BySets(lDef))
			least := a.Have(
				"L is included in each λ-system containing C",
				"∀H:set(set(A)). lambda_system_on(Ω, H) ∧ C ⊆ H ⇒ L ⊆ H",
				BySets(lDef))
			lambdaL := a.Have(
				"L is a λ-system",
				"lambda_system_on(Ω, L)",
				Derive(func(b *Argument) {
					inside := b.Have(
						"L lies within D, whose sets lie within the carrier",
						"L ⊆ {s:set(A) | s ⊆ Ω}",
						BySets(least.At(D), lambdaD, cInD, laws[0]))
					carrier := b.Have(
						"every λ-system on the carrier contains it",
						"Ω ∈ L",
						By(members, LambdaSystemDef))
					complements := b.Have(
						"relative complements stay in L",
						"∀s:set(A). s ∈ L ⇒ Ω ∖ s ∈ L",
						Derive(func(c *Argument) {
							s := c.FixAs[Set[A]]("s")
							inL := c.Assume()
							every := c.Have(
								"the complement lies in every λ-system containing C",
								"∀H:set(set(A)). lambda_system_on(Ω, H) ∧ C ⊆ H ⇒ Ω ∖ s ∈ H",
								Derive(func(d *Argument) {
									H := d.FixAs[Set[Set[A]]]("H")
									extension := d.Assume()
									d.Show(
										"such a system contains s and therefore its complement",
										By(extension, inL, members.At(s), LambdaSystemDef.At(Ω, H)))
								}))
							c.Show(
								"membership in every extension gives membership in L",
								By(members.At(c.TermAs[Set[A]]("Ω ∖ s")), every))
						}))
					unions := b.Have(
						"countable disjoint unions stay in L",
						"∀p:(num → set(A)). (∀n:num. p(n) ∈ L) ∧ (∀i j:num. i ≠ j ⇒ p(i) ∩ p(j) = ∅) ⇒ ⋃image(p, 𝕌) ∈ L",
						Derive(func(c *Argument) {
							c.FixAs[Fun[Nat, Set[A]]]("p")
							given := c.Conjuncts(
								c.Assume(),
								"each term is in L",
								"the terms are pairwise disjoint")
							terms, disjoint := given[0], given[1]
							every := c.Have(
								"the union lies in every λ-system containing C",
								"∀H:set(set(A)). lambda_system_on(Ω, H) ∧ C ⊆ H ⇒ ⋃image(p, 𝕌) ∈ H",
								Derive(func(d *Argument) {
									H := d.FixAs[Set[Set[A]]]("H")
									extension := d.Assume()
									inH := d.Have(
										"each term belongs to the extension",
										"∀n:num. p(n) ∈ H",
										By(extension, terms, members))
									d.Show(
										"the extension contains the disjoint union",
										By(extension, inH, disjoint, LambdaSystemDef.At(Ω, H)))
								}))
							c.Show(
								"membership in every extension gives membership in L",
								By(members.At(c.TermAs[Set[A]]("⋃image(p, 𝕌)")), every))
						}))
					b.Show(
						"the intersection has all the λ-system laws",
						By(inside, carrier, complements, unions, LambdaSystemDef.At(Ω, L)))
				}))
			extend := a.Have(
				"intersection with a fixed set extends from C to L by minimality",
				"∀s:set(A). s ∈ L ∧ (∀t:set(A). t ∈ C ⇒ s ∩ t ∈ L) ⇒ ∀t:set(A). t ∈ L ⇒ s ∩ t ∈ L",
				Derive(func(b *Argument) {
					s := b.FixAs[Set[A]]("s")
					given := b.Assume()
					H, hDef := b.LetAs[Set[Set[A]]]("H", "{t:set(A) | t ∈ L ∧ s ∩ t ∈ L}")
					containsC := b.Have(
						"C lies in the family of sets whose intersection with s lies in L",
						"C ⊆ H",
						BySets(hDef, generators, given))
					system := b.Have(
						"the family is a λ-system by closure under fixed intersections",
						"lambda_system_on(Ω, H)",
						By(lambdaL, given, hDef, At(fixedIntersection, Ω, L, s)))
					b.Show(
						"minimality of L puts every set of L in this family",
						BySets(least.At(H), system, containsC, hDef))
				}))
			firstPass := a.Have(
				"a generator can be intersected with any set of L",
				"∀s:set(A). s ∈ C ⇒ ∀t:set(A). t ∈ L ⇒ s ∩ t ∈ L",
				Derive(func(b *Argument) {
					s := b.FixAs[Set[A]]("s")
					inC := b.Assume()
					generatorIntersections := b.Have(
						"intersecting two generators gives another generator",
						"∀t:set(A). t ∈ C ⇒ s ∩ t ∈ L",
						BySets(generators, inC, piLaws))
					b.Show(
						"extend intersection from generators to L",
						BySets(generators, inC, generatorIntersections, extend.At(s)))
				}))
			allIntersections := a.Have(
				"any two sets of L can be intersected",
				"∀s:set(A). s ∈ L ⇒ ∀t:set(A). t ∈ L ⇒ s ∩ t ∈ L",
				Derive(func(b *Argument) {
					s := b.FixAs[Set[A]]("s")
					inL := b.Assume()
					generatorIntersections := b.Have(
						"commutativity gives intersections with generators",
						"∀u:set(A). u ∈ C ⇒ s ∩ u ∈ L",
						Derive(func(c *Argument) {
							u := c.FixAs[Set[A]]("u")
							inC := c.Assume()
							c.Show(
								"apply the first pass to the generator and commute the factors",
								By(Normalized, inL, inC, firstPass.At(u, s), set_algebra.InterComm.At(u, s)))
						}))
					b.Show(
						"extend intersection from generators to L again",
						By(inL, generatorIntersections, extend.At(s)))
				}))
			sigmaL := a.Have(
				"the intersection-closed λ-system L is a σ-algebra",
				"sigma_algebra_on(Ω, L)",
				By(lambdaL, allIntersections, At(sigmaFromIntersections, Ω, L)))
			a.Show(
				"the generated σ-algebra lies in L, and L lies in D",
				BySets(sigmaL, generators, least.At(D), lambdaD, cInD, GeneratedSigmaLeast.At(Ω, C, L)))
		})
	}),
})}
